static unsigned hal_writes,uart_bytes,deep_calls;static uint8_t uart_wire[64];static uint32_t irq_word;
static gb_flow helper_hal(void *p,gh_model *h,const gh_request *r,gb_scalar *out){(void)p;CHECK(h==&m.helpers);out->value=0;out->known=UINT32_MAX;if(r->kind==GH_MMIO_READ)return GB_RETURNED;if(r->kind==GH_MMIO_WRITE){hal_writes++;return GB_RETURNED;}if(r->kind==GH_NATIVE){deep_calls++;return GB_HALT;}return GB_HALT;}
static bs_flow boot_hal(void *p,bs_model *b,const bs_request *r,bs_result *out){(void)p;CHECK(b==&m.startup);out->known=UINT32_MAX;out->value=0;
    if(r->operation==BS_MMIO_READ){out->value=r->address==0x40004400?64:0;return BS_RETURNED;}
    if(r->operation==BS_MMIO_WRITE){hal_writes++;if(r->address==0x40004404){CHECK(uart_bytes<sizeof(uart_wire));if(uart_bytes<sizeof(uart_wire))uart_wire[uart_bytes++]=(uint8_t)r->value;}return BS_RETURNED;}
    if(r->operation==BS_JUMP||r->operation==BS_RESET_WAIT)return BS_TRANSFER;
    if(r->operation==BS_CSR_CLEAR)return BS_RETURNED;
    return BS_HALT;
}
static rk_flow kernel_hal(void *p,rk_model *k,const rk_request *r,rk_result *out){(void)p;CHECK(k==&m.kernel);out->value=0;out->known=UINT32_MAX;if(r->kind==RK_MMIO_READ){CHECK(r->target==0x4002420c);out->value=irq_word;return RK_RETURNED;}if(r->kind==RK_MMIO_WRITE){irq_word=r->arguments[0];return RK_RETURNED;}if(r->kind==RK_FENCE_I)return RK_RETURNED;return RK_HALT;}
